# POI label frame: a separate part that sits on top of a map,
# printed upside down (flat top on the bed) in two colours.
#
# A thin wall runs along the map edge; one bridge per point of interest runs
# from the frame towards its POI. The label is inlaid flush into the bridge's
# flat plate next to the frame (no stem underneath -- laid on the map it
# bridges over the terrain); past the label the plate tapers to a thin
# horizontal section, then a leg drops to the POI at 45° or steeper (its
# overhang when printed upside down). The underside is the negative of the
# terrain, so the part rests exactly on the map. Chamfers (plan view and a
# 45° gusset underneath) join each bridge to the frame.
#
# POIs come from the scene's list (props.TP3D_PG_poi), filled by the Map
# Generator (assets/poi_layer.js on both map generator pages) or "Add POI at
# 3D Cursor"; the picker helpers below are its Blender-side counterparts.

import json
import math
import uuid

import bmesh  # type: ignore
import bpy  # type: ignore
import numpy as np  # type: ignore
from mathutils import Matrix, Vector  # type: ignore
from mathutils.bvhtree import BVHTree  # type: ignore

from .. import constants as const
from . import geometry2d as g2d
from . import regenerate
from .mesh_ops import _clean_solid_mesh, _extrude_flat_polygon

FRAME_SUFFIX = "_POI_Frame"
TEXT_SUFFIX = "_POI_Text"

# Bridge direction presets: angle (degrees, counter-clockwise from east) the
# bridge runs from the POI towards the frame. None = nearest frame edge.
DIRECTION_ANGLES = {
    'AUTO': None,
    'E': 0.0, 'NE': 45.0, 'N': 90.0, 'NW': 135.0,
    'W': 180.0, 'SW': 225.0, 'S': 270.0, 'SE': 315.0,
}

# Keeps the frame's outer wall off the map's own side wall -- coplanar faces
# are the one thing the boolean solver reliably gets wrong.
_EDGE_INSET = 0.05
# Gap between the label and the ends of its flat plate section.
_TEXT_MARGIN = 1.0
# Station spacing (mm) along a bridge's leg, where it follows the terrain.
_SLOPE_STEP = 0.5
# Past the label the plate narrows down to the web over this length.
_PLATE_TAPER = 1.5
_MIN_TEXT_MM = 1.5
# Glyphs spanning the font's full vertical extent (ascenders, descenders).
_BAND_GLYPHS = "Hbdfghjklpqy"
# Free space beside the label's glyph band on each side of the bridge.
_LABEL_SIDE_MARGIN = 0.5
# Shortest horizontal run of the leg down to the POI (i.e. its steepest slope).
_MIN_RUN = 0.5
# 45° chamfer where a bridge meets the frame (both in plan view and as a
# gusset under the plate), easing the stress concentration at the joint.
_CHAMFER = 2.0


def _is_map(obj):
    return obj is not None and obj.type == 'MESH' and (
        obj.get("Object type") == "MAP" or obj.get("objType") == "MAP"
    )


def poi_world_xy(map_obj, lat, lon):
    """Blender world XY of a lat/lon, using the map's own horizontal scale
    (falls back to the scene's) so it stays correct in multi-scale scenes."""
    scale_hor = map_obj.get("Horizontal Scale") or bpy.context.scene.tp3d.sScaleHor
    x = const.R * math.radians(lon) * scale_hor
    y = const.R * math.log(math.tan(math.pi / 4 + math.radians(lat) / 2)) * scale_hor
    return x, y


def map_outline(map_obj):
    """2D outline of the map, taken from its flat underside.

    geometry2d.map_footprint_polygon() works from the top-surface silhouette,
    which on real terrain also picks up edges along steep faces -- dozens of
    bogus holes inside the outline. The map's floor is exact.
    """
    g2d._require_shapely()
    mw = map_obj.matrix_world
    mesh = map_obj.data
    if not mesh.vertices:
        return None
    zs = [(mw @ v.co).z for v in mesh.vertices]
    min_z = min(zs)
    tol = max(1e-4, (max(zs) - min_z) * 1e-4)
    polys = []
    for p in mesh.polygons:
        if all(zs[i] - min_z < tol for i in p.vertices):
            ring = [((mw @ mesh.vertices[i].co).x, (mw @ mesh.vertices[i].co).y) for i in p.vertices]
            poly = g2d.validate(g2d.Polygon(ring)) if len(ring) >= 3 else None
            if poly is not None and not poly.is_empty and poly.area > 0:
                polys.append(poly)
    outline = g2d.union(polys)
    if outline is None:
        fallback = g2d.map_footprint_polygon(map_obj)
        if fallback is None:
            return None
        outline = g2d.Polygon(fallback.exterior)
    parts = list(g2d.iter_polygons(outline))
    if not parts:
        return None
    biggest = max(parts, key=lambda pp: pp.area)
    return g2d.validate(g2d.Polygon(biggest.exterior).simplify(0.01))


class _Terrain:
    """Height lookups on the map's top surface (world space)."""

    def __init__(self, map_obj):
        depsgraph = bpy.context.evaluated_depsgraph_get()
        obj_eval = map_obj.evaluated_get(depsgraph)
        mesh = obj_eval.to_mesh()
        mw = map_obj.matrix_world
        verts = [mw @ v.co for v in mesh.vertices]
        polys = [tuple(p.vertices) for p in mesh.polygons]
        obj_eval.to_mesh_clear()
        self.tree = BVHTree.FromPolygons(verts, polys)
        zs = [v.z for v in verts]
        self.top = max(zs) + 1000.0
        self.floor = min(zs)
        self._verts = np.array([(v.x, v.y, v.z) for v in verts], dtype=np.float64)

    def height(self, x, y):
        hit = self.tree.ray_cast(Vector((x, y, self.top)), Vector((0, 0, -1)))
        return hit[0].z if hit[0] is not None else None

    def max_height(self, points):
        hs = [h for h in (self.height(x, y) for x, y in points) if h is not None]
        return max(hs) if hs else None

    def z_range(self, region):
        """(min, max) Z of mesh vertices strictly above the floor inside *region*."""
        v = self._verts
        above = v[:, 2] > self.floor + 1e-3
        inside = g2d._shapely.contains_xy(region, v[above, 0], v[above, 1])
        if not inside.any():
            return None, None
        zs = v[above, 2][inside]
        return float(zs.min()), float(zs.max())


def _text_polygon(text, font):
    """Filled 2D outline of *text* at font size 1, baseline at y=0, centered on x=0."""
    curve = bpy.data.curves.new(name="_tp3d_poi_text", type='FONT')
    curve.body = text
    curve.align_x = 'CENTER'
    curve.align_y = 'BOTTOM_BASELINE'
    curve.extrude = 0.0
    if font is not None:
        curve.font = font
    obj = bpy.data.objects.new("_tp3d_poi_text", curve)
    bpy.context.collection.objects.link(obj)
    try:
        depsgraph = bpy.context.evaluated_depsgraph_get()
        obj_eval = obj.evaluated_get(depsgraph)
        mesh = obj_eval.to_mesh()
        polys = []
        for p in mesh.polygons:
            ring = [(mesh.vertices[i].co.x, mesh.vertices[i].co.y) for i in p.vertices]
            if len(ring) < 3:
                continue
            poly = g2d.validate(g2d.Polygon(ring))
            if poly is not None and not poly.is_empty and poly.area > 0:
                polys.append(poly)
        obj_eval.to_mesh_clear()
    finally:
        bpy.data.objects.remove(obj, do_unlink=True)
        bpy.data.curves.remove(curve)
    return g2d.union(polys)


def _load_font(font_path):
    if not font_path:
        return None
    try:
        return bpy.data.fonts.load(bpy.path.abspath(font_path), check_existing=True)
    except (RuntimeError, OSError) as e:
        print(f"[TP3D poi_frame] Could not load font {font_path!r}, using Blender's default: {e}")
        return None


def _ray_hit(p, boundary, angle_deg, reach):
    """First point where a ray from *p* at *angle_deg* crosses *boundary*, or None."""
    rad = math.radians(angle_deg)
    ray = g2d.LineString([(p.x, p.y), (p.x + math.cos(rad) * reach, p.y + math.sin(rad) * reach)])
    hits = ray.intersection(boundary)
    if hits.is_empty:
        return None
    pts = [hits] if hits.geom_type == 'Point' else [h for h in getattr(hits, "geoms", []) if h.geom_type == 'Point']
    return min(pts, key=lambda h: h.distance(p)) if pts else None


def _new_object(name, verts, faces, material_name, origin):
    """Mesh object from world-space *verts*, stored relative to *origin*.

    Maps sit at their real Mercator position (thousands of mm from the world
    origin), where float32 vertex coordinates only resolve ~0.002 mm -- too
    coarse for small text, which then turns into sliver faces.
    """
    ox, oy = origin
    verts = [(x - ox, y - oy, z) for x, y, z in verts]
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(verts, [], faces)
    mesh.update()
    _clean_solid_mesh(mesh)
    bm = bmesh.new()
    bm.from_mesh(mesh)
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])
    bm.to_mesh(mesh)
    bm.free()
    mat = bpy.data.materials.get(material_name)
    if mat:
        mesh.materials.append(mat)
    obj = bpy.data.objects.new(name, mesh)
    obj.location = (ox, oy, 0.0)
    bpy.context.collection.objects.link(obj)
    return obj


def _prism_object(name, geom, bottom_z, top_z, material_name, origin):
    verts, faces = [], []
    for part in g2d.iter_polygons(geom):
        _extrude_flat_polygon(g2d, part, bottom_z, top_z, verts, faces)
    if not verts:
        return None
    return _new_object(name, verts, faces, material_name, origin)


def _loft_object(name, stations, ux, uy, material_name, origin):
    """Loft a rectangular cross-section along a straight bridge axis.

    *stations* is a list of (x, y, bottom_z, top_z, half_width) along the
    axis; *ux, uy* is the axis direction.
    """
    nx, ny = -uy, ux
    # Coincident stations would make zero-length (non-manifold) segments.
    unique = [stations[0]]
    for st in stations[1:]:
        if math.hypot(st[0] - unique[-1][0], st[1] - unique[-1][1]) > 1e-6:
            unique.append(st)
    stations = unique
    verts, faces = [], []
    for x, y, bottom, top, half in stations:
        for side, z in ((half, top), (-half, top), (-half, bottom), (half, bottom)):
            verts.append((x + nx * side, y + ny * side, z))
    for k in range(len(stations) - 1):
        a, b = k * 4, (k + 1) * 4
        for i in range(4):
            j = (i + 1) % 4
            faces.append((a + i, a + j, b + j, b + i))
    faces.append((3, 2, 1, 0))
    last = (len(stations) - 1) * 4
    faces.append((last, last + 1, last + 2, last + 3))
    return _new_object(name, verts, faces, material_name, origin)


def _hull_object(name, points, material_name, origin):
    """Convex solid spanned by world-space *points*."""
    bm = bmesh.new()
    verts = [bm.verts.new(p) for p in points]
    ret = bmesh.ops.convex_hull(bm, input=verts)
    junk = list({id(g): g for g in ret["geom_interior"] + ret["geom_unused"]
                 if isinstance(g, bmesh.types.BMVert)}.values())
    if junk:
        bmesh.ops.delete(bm, geom=junk, context='VERTS')
    bm.verts.ensure_lookup_table()
    hull_verts = [tuple(v.co) for v in bm.verts]
    index = {v: i for i, v in enumerate(bm.verts)}
    faces = [tuple(index[v] for v in f.verts) for f in bm.faces]
    bm.free()
    return _new_object(name, hull_verts, faces, material_name, origin)


def _apply_boolean(obj, operand, operation, solver=None):
    """Apply a boolean via the depsgraph rather than bpy.ops.modifier_apply,
    so it works from any context and never leaves a dangling modifier.

    MANIFOLD refuses non-manifold input (returning it unchanged), so EXACT
    is used whenever either side isn't watertight.
    """
    if solver is None:
        solver = 'MANIFOLD' if not _non_manifold_edges(obj) and not _non_manifold_edges(operand) else 'EXACT'
    mod = obj.modifiers.new(name="TP3D_POI_Boolean", type='BOOLEAN')
    mod.object = operand
    mod.operation = operation
    mod.solver = solver
    depsgraph = bpy.context.evaluated_depsgraph_get()
    depsgraph.update()
    new_mesh = bpy.data.meshes.new_from_object(obj.evaluated_get(depsgraph))
    obj.modifiers.remove(mod)
    old = obj.data
    obj.data = new_mesh
    new_mesh.name = old.name
    if old.users == 0:
        bpy.data.meshes.remove(old)


def _non_manifold_edges(obj):
    bm = bmesh.new()
    bm.from_mesh(obj.data)
    count = sum(1 for e in bm.edges if not e.is_manifold)
    bm.free()
    return count


def _remove_object(obj):
    if obj is None:
        return
    mesh = obj.data if obj.type == 'MESH' else None
    bpy.data.objects.remove(obj, do_unlink=True)
    if mesh is not None and mesh.users == 0:
        bpy.data.meshes.remove(mesh)


def map_uid(map_obj):
    """Stable id linking a map to its POI frame (names change, e.g. when a
    regeneration strips a ".001" suffix)."""
    uid = map_obj.get("tp3d_map_uid")
    if not uid:
        uid = map_obj["tp3d_map_uid"] = uuid.uuid4().hex
    return uid


def remove_poi_frame(map_obj):
    uid = map_uid(map_obj)
    for obj in list(bpy.data.objects):
        if obj.get("Object type") not in ("POI_FRAME", "POI_TEXT"):
            continue
        linked = obj.get("poiMapUid")
        if linked == uid:
            _remove_object(obj)
        elif linked is None and (
                obj.get("poiMap") == map_obj.name
                or (obj.matrix_world.translation.xy - map_obj.matrix_world.translation.xy).length < 1e-3):
            # Frames built before the id existed: recorded under this map's
            # name, or sitting exactly on its origin.
            _remove_object(obj)


def build_poi_frame(map_obj, pois, frame_width=1.0, bridge_width=0.0, tip_width=0.5,
                    text_size=3.75, plate_thickness=1.5, text_depth=0.6, clearance=0.2,
                    font_path=""):
    """Build the POI frame (and its inlaid text) for *map_obj*.

    *pois* is a list of dicts: {"name", "x", "y", "direction"} with x/y in
    Blender world space and direction a DIRECTION_ANGLES key. *tip_width*
    is the width of the thin part of each bridge.

    Returns (frame_obj, text_obj, warnings). frame_obj is None if nothing
    could be built; text_obj is None if no POI has a name.
    """
    import shapely.affinity as affinity  # deferred: Shapely is only guaranteed after _require_shapely()
    from shapely.ops import nearest_points

    from .primitives import setupColors  # deferred to avoid circular import at load time

    g2d._require_shapely()
    warnings = []

    footprint = map_outline(map_obj)
    if footprint is None:
        return None, None, [f"{map_obj.name}: could not determine the map outline."]

    outer = g2d.validate(footprint.buffer(-_EDGE_INSET, join_style='mitre'))
    inner = g2d.validate(footprint.buffer(-(frame_width + _EDGE_INSET), join_style='mitre'))
    if inner is None or inner.is_empty:
        return None, None, [f"{map_obj.name}: frame width {frame_width} mm leaves no room inside the map."]

    font = _load_font(font_path)
    ref = _text_polygon("H", font)
    cap_height = (ref.bounds[3] - ref.bounds[1]) if ref is not None else 0.7
    base_scale = text_size / cap_height if cap_height > 0 else text_size
    # The font's vertical glyph band (ascenders to descenders, font size 1,
    # baseline 0): labels are centred in it and the bridge sized to hold it.
    band = _text_polygon(_BAND_GLYPHS, font)
    band_lo, band_hi = (band.bounds[1], band.bounds[3]) if band is not None else (-0.25 * cap_height, cap_height)
    band_mid = (band_lo + band_hi) / 2
    if bridge_width <= 0:
        bridge_width = (band_hi - band_lo) * base_scale + 2 * _LABEL_SIDE_MARGIN
    tip_width = min(tip_width, bridge_width)
    plate_half = bridge_width / 2
    tip_half = tip_width / 2

    terrain = _Terrain(map_obj)
    frame_ring = g2d.validate(outer.difference(inner))
    _z_low, z_high = terrain.z_range(outer)
    if z_high is None:
        return None, None, [f"{map_obj.name}: no terrain found under the frame."]
    # Flat top: the plate's underside just clears the highest point of the map.
    top_z = z_high + plate_thickness
    bottom_z = terrain.floor + 0.05

    reach = 10.0 * max(map_obj.dimensions.x, map_obj.dimensions.y, 1.0)
    bridges = []  # (stations, ux, uy)
    chamfers = []  # point clouds of the chamfer solids (convex)
    plate_feet = []  # flat plate footprints near the frame
    labels = []
    for poi in pois:
        name = (poi.get("name") or "").strip()
        label = name or "POI"
        px, py = poi["x"], poi["y"]
        p = g2d.Point(px, py)

        part = next((pp for pp in g2d.iter_polygons(inner) if pp.contains(p)), None)
        if part is None:
            warnings.append(f"'{label}' lies on or outside the frame — skipped.")
            continue
        boundary = part.exterior

        direction = poi.get("direction") or 'AUTO'
        angle = poi.get("angle") if direction == 'CUSTOM' else DIRECTION_ANGLES.get(direction)
        if angle is None:
            # Shortest way to the frame -- hides the least terrain.
            q = nearest_points(boundary, p)[0]
        else:
            q = _ray_hit(p, boundary, angle, reach)
            if q is None:
                warnings.append(f"'{label}': no frame edge in direction {direction} — skipped.")
                continue

        dx, dy = q.x - px, q.y - py
        dist = math.hypot(dx, dy)
        if dist < 1e-6:
            warnings.append(f"'{label}' touches the frame — skipped.")
            continue
        ux, uy = dx / dist, dy / dist
        nx, ny = -uy, ux

        # Distances are measured from the POI along the bridge axis.
        z_tip = terrain.height(px, py)
        if z_tip is None:
            warnings.append(f"'{label}': no terrain under the POI — skipped.")
            continue
        tip_top = z_tip + plate_thickness
        # The leg drops from the flat top to the POI at 45° (run == drop);
        # printed upside down its slope is the overhang angle, so it may get
        # steeper (shorter run) but never shallower.
        drop = max(top_z - tip_top, 0.0)
        leg_run = drop
        glyphs = None
        text_len = 0.0
        if name:
            glyphs = _text_polygon(name, font)
            if glyphs is None or glyphs.is_empty:
                warnings.append(f"'{name}': could not render text.")
                glyphs = None
        if glyphs is not None:
            # Vertically: the font's glyph band centred on the bridge (same
            # baseline for every label). Horizontally: centred on the ink, not
            # on align_x's advance box -- the side bearings differ, which would
            # shift the text into one end of the box sized for its ink width.
            ink = glyphs.bounds
            glyphs = affinity.translate(glyphs, -(ink[0] + ink[2]) / 2, -band_mid)
            natural_w = ink[2] - ink[0]
            # Short bridge: steepen the leg (down to _MIN_RUN) before
            # shrinking the text.
            room_for_leg = dist - 2 * _TEXT_MARGIN - natural_w * base_scale
            if room_for_leg < leg_run:
                leg_run = max(min(leg_run, _MIN_RUN), room_for_leg)
            available = dist - leg_run - 2 * _TEXT_MARGIN
            scale = base_scale
            if natural_w * scale > available:
                scale = max(available, 0.0) / natural_w if natural_w > 0 else 0.0
                if scale * cap_height < _MIN_TEXT_MM:
                    warnings.append(f"'{name}': bridge too short for the label — text dropped.")
                    glyphs = None
                else:
                    warnings.append(f"'{name}': label shrunk to {scale * cap_height:.1f} mm to fit its bridge.")
        if glyphs is not None:
            text_len = natural_w * scale
            glyphs = affinity.scale(glyphs, scale, scale, origin=(0, 0))
            theta = math.degrees(math.atan2(uy, ux))
            # Keep the text readable from the south instead of upside down.
            if theta > 90.0 or theta <= -90.0:
                theta += 180.0
            glyphs = affinity.rotate(glyphs, theta, origin=(0, 0))
            # Label sits right next to the frame.
            mid = dist - _TEXT_MARGIN - text_len / 2
            glyphs = affinity.translate(glyphs, px + ux * mid, py + uy * mid)
            labels.append((name, g2d.validate(glyphs)))

        # Side view, POI -> frame: leg rising at >= 45° to the flat top, a
        # thin horizontal section, then the label plate bridging to the
        # frame. No stem anywhere -- laid on the map it spans over the terrain.
        flat_len = text_len + 2 * _TEXT_MARGIN if text_len else 0.0
        flat_start = max(dist - flat_len, 0.0)
        # _MIN_RUN only reserves room next to the label; the leg itself may be
        # as short as the drop allows (never shallower than 45°).
        leg_run = max(min(leg_run, flat_start), min(drop, _MIN_RUN), 1e-3)
        taper_start = max(flat_start - _PLATE_TAPER, 0.0)

        def half_at(sv):
            if sv >= flat_start:
                return plate_half
            if sv <= taper_start:
                return tip_half
            return tip_half + (plate_half - tip_half) * (sv - taper_start) / (flat_start - taper_start)

        def top_at(sv, half):
            if sv >= leg_run:
                return top_z
            top = tip_top + drop * sv / leg_run
            # Never let the terrain cut through the leg.
            sx, sy = px + ux * sv, py + uy * sv
            ground = terrain.max_height([(sx + nx * o, sy + ny * o) for o in (-half, 0.0, half)])
            if ground is not None:
                top = max(top, ground + plate_thickness)
            return min(top, top_z)

        # Run on until both sides of the plate reach the map edge, so a
        # bridge meeting the frame at a shallow angle still fuses with it
        # along its full width (it's clipped to the outline afterwards).
        side_hits = []
        for o in (-plate_half, 0.0, plate_half):
            start = g2d.Point(px + nx * o, py + ny * o)
            hit = _ray_hit(start, outer.exterior, math.degrees(math.atan2(uy, ux)), reach)
            if hit is not None:
                side_hits.append(hit.distance(start))
        end = (max(side_hits) if side_hits else dist + frame_width) + 0.5

        # Keep the leg as thick as the flat part measured across it (not
        # just vertically): its underside is the top line offset by t/cos(a),
        # mitred against the flat underside at the knee.
        slope = drop / leg_run if drop > 1e-6 else 0.0
        leg_t = plate_thickness * math.sqrt(1.0 + slope * slope)

        def bottom_at(sv, top):
            bottom = top - plate_thickness
            if slope:
                bottom = min(bottom, tip_top + slope * sv - leg_t)
            # Gusset under the plate against the frame wall (45°).
            gusset_start = dist - _CHAMFER
            if sv > gusset_start:
                bottom = min(bottom, top_z - plate_thickness - (sv - gusset_start))
            # Never below the map's floor: the terrain cut only removes what's
            # inside the map, so anything under it would be left dangling.
            return max(bottom, bottom_z)

        n_leg = max(1, int(math.ceil(leg_run / _SLOPE_STEP)))
        axis = {leg_run * k / n_leg for k in range(n_leg + 1)}
        axis |= {taper_start + (flat_start - taper_start) * k / 4 for k in range(5)}
        axis |= {max(dist - _CHAMFER, 0.0), dist, end}
        if slope:
            # Where the leg's underside meets the flat underside (the knee).
            knee = (top_z - plate_thickness + leg_t - tip_top) / slope
            if 0.0 < knee < end:
                axis.add(knee)
        def station(sv, top, half):
            return (px + ux * sv, py + uy * sv, bottom_at(sv, top), top, half)

        stations = []
        prev = None
        for sv in sorted(axis):
            half = half_at(sv)
            top = top_at(sv, half)
            if prev is not None:
                # The leg must keep rising at >= 45° (its overhang when printed
                # upside down) -- following the terrain can flatten it, and a
                # leg start raised over high terrain would otherwise reach the
                # flat top too gently. Lift, or insert a 45° knee.
                need = prev[1] + (sv - prev[0])
                if need > top_z and prev[1] < top_z - 1e-9:
                    knee = prev[0] + (top_z - prev[1])
                    if knee < sv - 1e-6:
                        stations.append(station(knee, top_z, half_at(knee)))
                top = min(max(top, need), top_z)
            prev = (sv, top)
            stations.append(station(sv, top, half))

        # Plan-view chamfers: a 45° triangle on each side of the plate where
        # it meets the frame, reaching into the wall so it fuses with it.
        # Underneath, a corner face slopes at 45° both along the bridge and
        # along the wall: along the plate's side it continues the plate's
        # gusset exactly (depth _CHAMFER + past), and it runs out to nothing
        # at the flare's far tip on the wall instead of ending in a spike.
        def chamfer_bottom(x, y, a, wall_dir):
            past = (x - q.x) * ux + (y - q.y) * uy  # > 0 inside the wall
            along = max((x - a.x) * wall_dir[0] + (y - a.y) * wall_dir[1], 0.0)
            depth = max(min(_CHAMFER + past, _CHAMFER - along), 0.0)
            return max(top_z - plate_thickness - depth, bottom_z)

        for side in (-1.0, 1.0):
            start = g2d.Point(px + nx * plate_half * side, py + ny * plate_half * side)
            a = _ray_hit(start, boundary, math.degrees(math.atan2(uy, ux)), reach)
            if a is None:
                continue
            along = boundary.project(a)
            length = boundary.length
            cands = [boundary.interpolate((along + d) % length) for d in (_CHAMFER, -_CHAMFER)]
            # The one pointing away from the bridge.
            b = max(cands, key=lambda c: ((c.x - px) * nx + (c.y - py) * ny) * side)
            wall = frame_width * 0.5
            b_dx, b_dy = b.x - a.x, b.y - a.y
            b_len = math.hypot(b_dx, b_dy) or 1.0
            # Outward (into the wall) = perpendicular to a->b, away from the POI.
            ox, oy = -b_dy / b_len, b_dx / b_len
            if (ox * (a.x - px) + oy * (a.y - py)) < 0:
                ox, oy = -ox, -oy
            outline = [
                (a.x - ux * _CHAMFER, a.y - uy * _CHAMFER),
                (a.x + ox * wall, a.y + oy * wall),
                (b.x + ox * wall, b.y + oy * wall),
                (b.x, b.y),
            ]
            wall_dir = (b_dx / b_len, b_dy / b_len)
            # The wall corner under the plate's side is the deepest point.
            deep = [(a.x, a.y), (a.x + ox * wall, a.y + oy * wall)]
            # Every point also at the top, so the hull's top stays one flat face.
            chamfers.append([(x, y, top_z) for x, y in outline + deep]
                            + [(x, y, chamfer_bottom(x, y, a, wall_dir)) for x, y in outline + deep])

        # Plan footprint of the flat plate near the frame -- used to fill
        # narrow gaps where the plate meets the wall at a shallow angle.
        foot_start = max(leg_run, flat_start, dist - 3 * _CHAMFER)
        if foot_start < end:
            plate_feet.append(g2d.Polygon([
                (px + ux * foot_start + nx * plate_half, py + uy * foot_start + ny * plate_half),
                (px + ux * end + nx * plate_half, py + uy * end + ny * plate_half),
                (px + ux * end - nx * plate_half, py + uy * end - ny * plate_half),
                (px + ux * foot_start - nx * plate_half, py + uy * foot_start - ny * plate_half),
            ]))
        bridges.append((stations, ux, uy))

    if not bridges:
        warnings.append(f"{map_obj.name}: no POI inside the map's inner area — only the frame was built.")

    for i, (name_a, poly_a) in enumerate(labels):
        for name_b, poly_b in labels[i + 1:]:
            if poly_a.intersects(poly_b):
                warnings.append(f"Labels '{name_a}' and '{name_b}' overlap — change one's direction.")

    setupColors()
    remove_poi_frame(map_obj)

    origin = tuple(map_obj.matrix_world.translation.xy)
    parts = []
    # Frame: a plain wall along the map edge.
    frame_obj = _prism_object(map_obj.name + FRAME_SUFFIX, frame_ring, bottom_z, top_z, "BLACK", origin)
    if frame_obj is None:
        return None, None, warnings + [f"{map_obj.name}: POI frame came out empty."]

    # Bridges run past the map edge; clip them just inside the frame's outer
    # wall (not flush with it -- coplanar faces trip up the boolean solver).
    clip = _prism_object("_tp3d_poi_clip", outer.buffer(-min(0.02, frame_width * 0.25), join_style='mitre'),
                         bottom_z - 1.0, top_z + 1.0, "BLACK", origin)
    for k, (stations, ux, uy) in enumerate(bridges):
        bridge = _loft_object(f"_tp3d_poi_bridge_{k}", stations, ux, uy, "BLACK", origin)
        if clip is not None:
            _apply_boolean(bridge, clip, 'INTERSECT')
        parts.append(bridge)
    _remove_object(clip)
    for k, points in enumerate(chamfers):
        parts.append(_hull_object(f"_tp3d_poi_chamfer_{k}", points, "BLACK", origin))

    # Fill gaps narrower than 2 * _CHAMFER between plates and the frame (a
    # plate meeting the wall at a shallow angle leaves a thin wedge that
    # would print as a slot): morphological closing, kept near the wall.
    if plate_feet:
        joined = g2d.union([frame_ring] + plate_feet)
        closed = joined.buffer(_CHAMFER, quad_segs=8).buffer(-_CHAMFER, quad_segs=8)
        near_wall = g2d.validate(outer.difference(inner.buffer(-3 * _CHAMFER, join_style='mitre')))
        fill = g2d.validate(closed.difference(joined).intersection(near_wall))
        fill = g2d.union([pp for pp in g2d.iter_polygons(fill, min_area=0.05)])
        if fill is not None:
            parts.append(_prism_object("_tp3d_poi_fill", fill.buffer(0.05, join_style='mitre').intersection(outer),
                                       top_z - plate_thickness, top_z, "BLACK", origin))
    for part in parts:
        if part is None:
            continue
        _apply_boolean(frame_obj, part, 'UNION')
        _remove_object(part)

    # Underside = negative of the terrain.
    _apply_boolean(frame_obj, map_obj, 'DIFFERENCE')

    text_obj = None
    text2d = g2d.union([poly for _n, poly in labels])
    if text2d is not None and not text2d.is_empty:
        # Small text produces near-touching glyph slivers that earcut turns
        # into non-manifold walls; snap to a fine grid and drop the slivers.
        text2d = g2d.validate(g2d._shapely.set_precision(text2d, 0.001).buffer(0.005).buffer(-0.005))
        # Labels win over the frame (the recess cuts through it); only keep
        # them clear of the map's outer edge.
        text2d = g2d.validate(text2d.intersection(outer.buffer(-0.3, join_style='mitre')))
    if text2d is not None and not text2d.is_empty:
        depth = min(text_depth, plate_thickness * 0.6)
        cutter = _prism_object("_tp3d_poi_text_cutter", text2d, top_z - depth, top_z + 1.0, "WHITE", origin)
        if cutter is not None:
            _apply_boolean(frame_obj, cutter, 'DIFFERENCE')
            _remove_object(cutter)
        text_obj = _prism_object(map_obj.name + TEXT_SUFFIX, text2d, top_z - depth, top_z, "WHITE", origin)

    # The terrain and text cuts carry their own materials over; the frame is
    # one color.
    black = bpy.data.materials.get("BLACK")
    frame_obj.data.materials.clear()
    if black:
        frame_obj.data.materials.append(black)
    for poly in frame_obj.data.polygons:
        poly.material_index = 0

    if _non_manifold_edges(frame_obj):
        warnings.append(f"{frame_obj.name}: result is not watertight — check it before printing.")

    # New objects' matrix_world only updates with the view layer; the
    # generation tag below records it as the "unmoved" reference.
    bpy.context.view_layer.update()
    lift = Matrix.Translation((0, 0, clearance))
    for obj in (frame_obj, text_obj):
        if obj is None:
            continue
        obj.data.transform(lift)
        obj.data.update()
        obj["Object type"] = "POI_FRAME" if obj is frame_obj else "POI_TEXT"
        obj["Addon"] = const.ADDON_NAME
        obj["Version"] = const.ADDON_VERSION
        obj["poiMap"] = map_obj.name
        obj["poiMapUid"] = map_uid(map_obj)
        if map_obj.get(regenerate.GEN_ID):
            # Belongs to its map's generation: replaced along with it.
            regenerate.tag_generated(obj, map_obj[regenerate.GEN_ID])
        # Own export group: frame + text are one two-color print, separate from the map.
        obj["ExportGroup"] = 3

    frame_obj["poiSettings"] = json.dumps({
        "frame_width": frame_width, "bridge_width": bridge_width, "tip_width": tip_width,
        "text_size": text_size, "plate_thickness": plate_thickness, "text_depth": text_depth,
        "clearance": clearance,
    })
    return frame_obj, text_obj, warnings


def generate_poi_frames(tp3d, map_objs):
    """Build a POI frame on every map in *map_objs* that contains at least
    one enabled POI from the scene's POI list.

    Returns (built_frame_objs, warnings).
    """
    g2d._require_shapely()
    pois = [p for p in tp3d.pois if p.enabled]
    built, warnings = [], []
    if not pois:
        return built, ["No enabled points of interest in the list."]

    for map_obj in map_objs:
        if not _is_map(map_obj):
            continue
        outline = map_outline(map_obj)
        if outline is None:
            warnings.append(f"{map_obj.name}: could not determine the map outline.")
            continue
        entries = []
        for p in pois:
            x, y = poi_world_xy(map_obj, p.lat, p.lon)
            if outline.contains(g2d.Point(x, y)):
                entries.append({"name": p.name, "x": x, "y": y, "direction": p.direction, "angle": p.angle})
        if not entries:
            continue
        frame_obj, _text_obj, w = build_poi_frame(
            map_obj, entries,
            frame_width=tp3d.poi_frameWall, bridge_width=tp3d.poi_bridgeWidth,
            tip_width=tp3d.poi_tipWidth, text_size=tp3d.poi_labelSize,
            plate_thickness=tp3d.poi_thickness, text_depth=tp3d.poi_textDepth,
            clearance=tp3d.poi_clearance,
            font_path=tp3d.textFont,
        )
        warnings.extend(w)
        if frame_obj is not None:
            built.append(frame_obj)
    return built, warnings


# ---------------------------------------------------------------------------
# Operator / picker helpers
# ---------------------------------------------------------------------------

POI_SETTING_PROPS = ("poi_frameWall", "poi_bridgeWidth", "poi_tipWidth", "poi_labelSize",
                     "poi_thickness", "poi_textDepth", "poi_clearance")


def map_objects_for_poi(context):
    """Selected maps, or every map in the scene if none is selected."""
    selected = [o for o in context.selected_objects if _is_map(o)]
    return selected or [o for o in context.scene.objects if _is_map(o)]


def poi_state_for_picker(tp3d):
    """POI list + frame settings, served to the Map Generator page so its
    preview matches what Blender will build (and edits made in Blender show
    up there). Includes the font file the labels are built with."""
    import os

    pois = []
    for p in tp3d.pois:
        angle = p.angle if p.direction == 'CUSTOM' else DIRECTION_ANGLES.get(p.direction)
        pois.append({"name": p.name, "lat": p.lat, "lon": p.lon, "angle": angle, "enabled": p.enabled})
    font_path = bpy.path.abspath(tp3d.textFont) if tp3d.textFont else ""
    if not os.path.isfile(font_path):
        # Blender's built-in text font ("Bfont Regular") is Inter.
        fonts_dir = bpy.utils.system_resource('DATAFILES', path="fonts")
        font_path = os.path.join(fonts_dir, "Inter.woff2") if fonts_dir else ""
    return {
        "fontPath": font_path if os.path.isfile(font_path) else "",
        "pois": pois,
        "settings": {
            "frameWidth": tp3d.poi_frameWall, "bridgeWidth": tp3d.poi_bridgeWidth,
            "tipWidth": tp3d.poi_tipWidth, "textSize": tp3d.poi_labelSize,
        },
    }


def store_picker_pois(tp3d, pois, settings=None):
    """Replace the scene's POI list (and frame settings) with the picker's.

    A POI with an angle (dragged in the picker) becomes a Custom direction;
    without one it's Auto (shortest path to the frame). *settings* only
    carries the values the user actually edited in the picker.
    """
    if settings:
        for key, prop in (("frameWidth", "poi_frameWall"), ("bridgeWidth", "poi_bridgeWidth"),
                          ("textSize", "poi_labelSize")):
            try:
                setattr(tp3d, prop, float(settings[key]))
            except (KeyError, TypeError, ValueError):
                pass
    tp3d.pois.clear()
    for entry in pois:
        try:
            lat, lon = float(entry["lat"]), float(entry["lon"])
        except (KeyError, TypeError, ValueError):
            continue
        poi = tp3d.pois.add()
        poi.name = str(entry.get("name") or "")[:64]
        poi.lat, poi.lon = lat, lon
        poi.enabled = bool(entry.get("enabled", True))
        angle = entry.get("angle")
        if isinstance(angle, (int, float)):
            poi.direction = 'CUSTOM'
            poi.angle = ((float(angle) + 180.0) % 360.0) - 180.0
    tp3d.poi_index = 0


def build_picker_poi_frames(context, map_objs, overlay, pct):
    """Build POI frames on *map_objs* during a picker run, routing problems
    to the warnings overlay (no operator self.report() available there)."""
    from .. import progress as _progress

    overlay.update(pct, "Building POI frame…", f"{len(context.scene.tp3d.pois)} POI(s)…")
    try:
        built, warnings = generate_poi_frames(context.scene.tp3d, map_objs)
    except ImportError as e:
        _progress.WarningsOverlay.add_warning(f"POI frame skipped: {e}", "warn")
        return []
    for w in warnings:
        _progress.WarningsOverlay.add_warning(w, "warn")
    if built:
        overlay.add_completed_step(f"POI frame — {len(built)} built")
    elif map_objs:
        _progress.WarningsOverlay.add_warning("No POI frame built — are the POIs inside a map?", "warn")
    return built


def apply_picker_result(context, data, new_maps, overlay, pct):
    """Map Generator hook: store the page's POIs and, if asked, build the
    label frame on *new_maps* -- or, for a POI-only send, on every map in
    the scene. Returns the built frames."""
    if 'pois' not in data:  # page without POI support
        return []
    pois = data.get('pois') or []
    # Stored even when empty: deleting every POI in the page clears the list.
    store_picker_pois(context.scene.tp3d, pois, data.get('poiSettings'))
    if not pois or not data.get('poiFrame', True):
        return []
    maps = new_maps or [o for o in context.scene.objects if _is_map(o)]
    return build_picker_poi_frames(context, maps, overlay, pct)

